styles:
/* ===== Single job posting (scoped) ===== */
.page-career .career-hero { padding-top: clamp(140px, 18vh, 220px); padding-bottom: clamp(28px, 4vw, 50px); }
.page-career .career-hero__back {
  display: inline-flex; align-items: center; gap: 8px;
  color: var(--grey-500); font-size: 15px; margin-bottom: clamp(22px, 3vw, 38px);
  transition: color .25s var(--ease);
}
.page-career .career-hero__back:hover { color: var(--red); }
.page-career .career-hero__back .arrow { transform: rotate(180deg); display: inline-grid; }
.page-career .career-hero__eyebrow { color: var(--red); font-size: clamp(15px, 1.2vw, 18px); margin-bottom: 16px; }
.page-career .career-hero__title {
  font-family: var(--font-display);
  font-size: clamp(44px, 7vw, 104px);
  line-height: 1.04; color: var(--grey-700); letter-spacing: -0.01em;
}

/* meta row */
.page-career .career-meta {
  display: flex; flex-wrap: wrap; gap: clamp(14px, 2vw, 28px);
  margin-top: clamp(24px, 3vw, 40px);
}
.page-career .career-meta__item {
  display: flex; flex-direction: column; gap: 4px;
  border: 1px solid var(--line); border-radius: var(--radius);
  padding: 14px 22px; min-width: 150px; background: var(--bg-alt);
}
.page-career .career-meta__label {
  font-size: 12px; letter-spacing: .12em; text-transform: uppercase; color: var(--grey-500);
}
.page-career .career-meta__value {
  font-family: var(--font-display); font-size: clamp(17px, 1.4vw, 21px); color: var(--grey-900);
}

/* hero media */
.page-career .career-figure { margin-top: clamp(30px, 4vw, 56px); border-radius: var(--radius-lg); overflow: hidden; background: var(--bg-alt); }
.page-career .career-figure img { width: 100%; height: clamp(220px, 42vw, 520px); object-fit: cover; }

/* readable single-column body */
.page-career .career-body { max-width: 760px; margin-inline: auto; }
.page-career .career-block + .career-block { margin-top: clamp(40px, 5vw, 68px); }
.page-career .career-block h2 {
  font-family: var(--font-display); font-size: clamp(28px, 3.4vw, 44px);
  color: var(--grey-900); line-height: 1.1; margin-bottom: clamp(16px, 2vw, 26px);
}
.page-career .career-block p { color: var(--grey-700); font-size: clamp(16px, 1.15vw, 19px); line-height: 1.75; }
.page-career .career-block p + p { margin-top: 16px; }
.page-career .career-block p.lead {
  font-family: var(--font-display); color: var(--red);
  font-size: clamp(20px, 2vw, 28px); line-height: 1.3;
}
.page-career .career-list { display: flex; flex-direction: column; gap: 14px; }
.page-career .career-list li {
  position: relative; padding-left: 30px;
  color: var(--grey-700); font-size: clamp(16px, 1.1vw, 18px); line-height: 1.6;
}
.page-career .career-list li::before {
  content: ""; position: absolute; left: 4px; top: .62em;
  width: 9px; height: 9px; border-radius: 50%; background: var(--red);
}

/* apply box */
.page-career .career-apply {
  background: var(--bg-alt); border: 1px solid var(--line);
  border-radius: var(--radius-lg); padding: clamp(30px, 4vw, 56px);
  text-align: center; margin-top: clamp(44px, 5vw, 72px);
}
.page-career .career-apply h2 { margin-bottom: 14px; }
.page-career .career-apply p { max-width: 52ch; margin-inline: auto; }
.page-career .career-apply .cta__btn { margin-top: 30px; }

.page-career .career-allroles { text-align: center; margin-top: clamp(30px, 4vw, 48px); }
.page-career .career-allroles a {
  display: inline-flex; align-items: center; gap: 10px;
  color: var(--red); font-size: 17px;
}
.page-career .career-allroles a .arrow { transform: rotate(180deg); display: inline-grid; }

@media (max-width: 560px) {
  .page-career .career-meta__item { flex: 1 1 100%; }
}
